<script lang="ts">
  import { onMount } from 'svelte';
  import { invoke } from '@tauri-apps/api/core';
  import { listen } from '@tauri-apps/api/event';
  import { LocalRgbaPresenter } from './rgba';
  import { applyDelta, LatestFrameDecoder, parseFrame, type FrameAck, type FrameHeader, type PresentationMode, type Snapshot } from './session';
  import { CameraGestureController, MutationQueue, pickCoordinates, wheelPixels, type CameraMode } from './camera-input';
  type Model={id:string;label:string;source:string;state:string;kind:string;thumbnail?:string}; type Layer=Record<string,any>;
  const names:Record<string,string>={wash:'Wash','flat-fill':'Flat fill','shadow-hatch':'Shadow hatch',silhouette:'Contour',creases:'Crease','form-lines':'Form lines',construction:'Construction',paper:'Paper'};
  let snapshot=$state<Snapshot|null>(null),connection=$state('Connecting'),status=$state('Opening Drawing Studio…'),error=$state(''),pending=$state(false);
  let canvas=$state<HTMLCanvasElement>(undefined!),rgbaCanvas=$state<HTMLCanvasElement>(undefined!),viewport=$state<HTMLDivElement>(undefined!),socket:WebSocket|undefined,rgba:LocalRgbaPresenter|undefined;
  let mode=$state<PresentationMode>('native_gpu'),activeMode=$state<PresentationMode|null>(null),presentationError=$state(''),nativeUnavailable:string|null=null,generation=0,viewportKey='',nativeRectKey='',renderSize=$state<[number,number]>([1,1]),fps=$state(0),lastFrame=$state(0),frames=0,resyncing=false;
  let cameraMode=$state<CameraMode>('select'),showModels=$state(false),selectedLayerId=$state<string|undefined>(),newSource=$state('silhouette'),chosenBrush=$state<any>(),buildUp=$state(1),soloLayer=$state<string|undefined>(),gestureId=0,activeGesture:number|undefined,navigationFrame:number|undefined,nativeFocused=false;
  const gestures=new CameraGestureController(),mutations=new MutationQueue();
  const domain=$derived(snapshot?.values.npr),settings=$derived(domain?.settings),layers=$derived((settings?.style_layers?.layers??[]) as Layer[]),selectedLayer=$derived(layers.find(x=>x.id===selectedLayerId));
  const models=$derived((snapshot?.values.models??[]) as Model[]),visibleModels=$derived(models.filter(x=>x.state==='ready')),selectedModel=$derived(visibleModels.find(x=>x.id===settings?.selected));
  const brushes=$derived((domain?.brushes?.brushes??{}) as Record<string,any[]>),brushList=$derived(Object.values(brushes).flat() as any[]),diagnostics=$derived(domain?.layer_diagnostics??{}),drafts=$derived(domain?.drafts??{}),variants=$derived(domain?.variants??{}),looks=$derived((domain?.available_looks??[]) as string[]);
  const documentStatus=$derived(error||(pending?'Applying…':domain?.dirty?'Unsaved changes':status));
  $effect(()=>{if(layers.length&&!layers.some(x=>x.id===selectedLayerId))selectedLayerId=layers.find(x=>x.source!=='paper')?.id??layers[0].id;});
  const title=(x:string)=>x.split(/[-_]/).map(w=>w[0]?.toUpperCase()+w.slice(1)).join(' '),surface=(x:string)=>x==='wash'||x==='flat-fill',compatible=(b:any,x:string)=>b.applications?.includes(surface(x)?'surface':'stroke');
  function dispatch(control:string,intent:Record<string,unknown>){if(!snapshot||resyncing||socket?.readyState!==WebSocket.OPEN)return;mutations.push(control,intent);pending=true;error='';schedule();}
  function schedule(){pending=mutations.busy;if(navigationFrame===undefined)navigationFrame=requestAnimationFrame(flush);}
  function flush(){navigationFrame=undefined;if(resyncing||!snapshot||socket?.readyState!==WebSocket.OPEN)return;const action=mutations.take(snapshot.revision);pending=mutations.busy;if(action){const {queued_at,...request}=action;socket.send(JSON.stringify({type:'action',action:request}));}}
  function commit(next:Layer[]){if(settings)dispatch('layer.edit',{kind:'set_look',style:settings.global,layers:{...settings.style_layers,layers:next}});}
  function update(id:string,change:Record<string,any>){commit(layers.map(x=>x.id===id?{...x,...change}:x));}
  function layerId(source:string){let id=source,n=1;while(layers.some(x=>x.id===id))id=`${source}-${++n}`;return id;}
  function useBrush(brush:any){if(!selectedLayer||selectedLayer.source==='paper'||!compatible(brush,selectedLayer.source))return;update(selectedLayer.id,{brush:{brush:{id:brush.id,version:brush.version}}});}
  function addLayer(brush:any){if(layers.length>=32||!compatible(brush,newSource))return;const template=layers.find(x=>x.source===newSource);if(!template)return;const id=layerId(newSource);commit([...layers,{...template,id,label:`${names[newSource]} ${id.split('-').at(-1)}`,enabled:true,opacity:1,brush:{brush:{id:brush.id,version:brush.version}}}]);selectedLayerId=id;}
  function duplicate(){if(!selectedLayer||selectedLayer.source==='paper'||layers.length>=32)return;const id=layerId(selectedLayer.source);commit([...layers,{...selectedLayer,id,label:`${selectedLayer.label} copy`}]);selectedLayerId=id;}
  function remove(){if(selectedLayer?.source!=='paper')commit(layers.filter(x=>x.id!==selectedLayerId));}
  function move(delta:number){if(!selectedLayer||selectedLayer.source==='paper')return;const from=layers.findIndex(x=>x.id===selectedLayer.id),to=from+delta;if(to<1||to>=layers.length)return;const next=[...layers];[next[from],next[to]]=[next[to],next[from]];commit(next);}
  function selectModel(model:Model){if(model.id!==settings?.selected)dispatch('source.select',{kind:'select_model',model:model.id});showModels=false;}
  function lock(layer:Layer){dispatch('layer.lock',{kind:'set_layer_lock',layer:layer.id,locked:!(domain?.locked_layers??[]).includes(layer.id)});}
  function toggleSolo(){const next=soloLayer===selectedLayerId?undefined:selectedLayerId;soloLayer=next;dispatch('layer.solo',{kind:'set_solo_layer',layer:next??null});}
  function setBuildUp(value:number){buildUp=value;dispatch('layer.build-up',{kind:'set_build_up',value});}
  function reset(){navigate('reset');} function coverage(){dispatch('layer.coverage',{kind:'set_debug_view',view:settings?.debug==='FeatureClasses'?'Final':'FeatureClasses'});}
  function syncNative(){if(!viewport||nativeUnavailable)return;const r=viewport.getBoundingClientRect(),rect={left:r.left,top:r.top,width:r.width,height:r.height,dpr:devicePixelRatio,visible:!document.hidden&&(activeMode==='native_gpu'||mode==='native_gpu')},key=JSON.stringify(rect);if(key!==nativeRectKey){nativeRectKey=key;void invoke('viewport_rect',{rect}).catch(x=>presentationError=String(x));}}
  function requestViewport(interacting=false){if(socket?.readyState!==WebSocket.OPEN||!viewport||(mode!=='jpeg'&&nativeUnavailable))return;const r=viewport.getBoundingClientRect();if(!r.width||!r.height)return;const key=`${r.width}:${r.height}:${devicePixelRatio}:${mode}`;if(key!==viewportKey){generation++;viewportKey=key;}socket.send(JSON.stringify({type:'viewport',request:{mode,generation,adaptive_resolution:false,css_width:r.width,css_height:r.height,dpr:devicePixelRatio,interacting,high_quality_capture:false}}));syncNative();}
  function present(h:FrameHeader){if(h.generation!==generation||h.mode!==mode)return;activeMode=h.mode;renderSize=h.size;frames++;lastFrame=performance.now();syncNative();} function fail(x:string){presentationError=x;if(mode!=='jpeg'){mode='jpeg';viewportKey='';requestViewport();}} function consumed(a:FrameAck){if(a.generation!==generation)return;} function nativeAck(a:FrameAck){consumed(a);void invoke('frame_consumed',{ack:a}).catch(x=>fail(String(x)));}
  function begin(){if(activeGesture!==undefined)return;activeGesture=++gestureId;dispatch('viewport',{kind:'begin_camera_gesture',gesture_id:activeGesture});} function end(){if(activeGesture===undefined)return;dispatch('viewport',{kind:'end_camera_gesture',gesture_id:activeGesture});activeGesture=undefined;} function cancel(){const p=gestures.cancel();if(p!==undefined&&viewport?.hasPointerCapture(p))viewport.releasePointerCapture(p);end();requestViewport();}
  function navigate(kind:string,dx=0,dy=0,wheel=0,x=0,y=0){if((!nativeFocused&&document.activeElement!==viewport)||!viewport||resyncing)return;const r=viewport.getBoundingClientRect();dispatch('viewport',{kind:'navigate',mode:kind,dx,dy,wheel,x,y,width:kind==='select'?renderSize[0]:Math.max(1,Math.round(r.width)),height:kind==='select'?renderSize[1]:Math.max(1,Math.round(r.height)),focused:true});requestViewport(true);}
  function down(e:PointerEvent){if(!gestures.down(e.pointerId,e.button,e.clientX,e.clientY,cameraMode))return;e.preventDefault();viewport.focus();viewport.setPointerCapture(e.pointerId);begin();} function pointerMove(e:PointerEvent){const m=gestures.move(e.pointerId,e.clientX,e.clientY);if(m)navigate(m.mode,m.dx,m.dy,m.wheel);} function up(e:PointerEvent){if(!gestures.owns(e.pointerId))return;pointerMove(e);if(gestures.up(e.pointerId,e.clientX,e.clientY)){const [x,y]=pickCoordinates(e.clientX,e.clientY,viewport.getBoundingClientRect(),renderSize);navigate('select',0,0,0,x,y);}if(viewport.hasPointerCapture(e.pointerId))viewport.releasePointerCapture(e.pointerId);end();requestViewport();}
  onMount(()=>{const boot=(window as any).__PLAYGROUND__;if(!boot){connection='Disconnected';error='Open this drawing from an active Amigo scene.';return;}nativeUnavailable=boot.native_error??null;if(nativeUnavailable)mode='jpeg';try{rgba=new LocalRgbaPresenter(rgbaCanvas,h=>h.generation===generation&&mode==='local_rgba',present,nativeAck,fail);}catch(x){fail(String(x));}const decoder=new LatestFrameDecoder((img,h)=>{if(canvas.width!==img.width)canvas.width=img.width;if(canvas.height!==img.height)canvas.height=img.height;canvas.getContext('2d')?.drawImage(img,0,0);present(h);},fail,a=>{consumed(a);socket?.send(JSON.stringify({type:'frame_ack',ack:a}));},h=>h.generation===generation&&h.mode===mode);const listeners=Promise.all([listen<FrameHeader>('viewport-presented',e=>present(e.payload)),listen<FrameAck>('viewport-consumed',e=>consumed(e.payload)),listen<{slot:number;header:FrameHeader}>('viewport-rgba-frame',e=>rgba?.push(e.payload.slot,e.payload.header)),listen<{generation:number;message:string}>('viewport-error',e=>fail(e.payload.message))]);socket=new WebSocket(boot.endpoint);socket.binaryType='blob';socket.onopen=async()=>{await listeners;socket?.send(JSON.stringify({version:boot.version,playground:boot.playground,token:boot.token}));connection='Connected';requestViewport();};socket.onmessage=e=>{if(e.data instanceof Blob){void parseFrame(e.data).then(x=>decoder.push(x)).catch(x=>error=String(x));return;}try{const m=JSON.parse(e.data);if(m.type==='snapshot'){snapshot=m.snapshot;resyncing=false;status='Ready';schedule();}else if(m.type==='accepted'){if(mutations.accepted(m.request_id,m.revision,snapshot?.revision??0))schedule();}else if(m.type==='delta'&&snapshot){if(snapshot.revision!==m.base_revision){resyncing=true;socket?.send(JSON.stringify({type:'refresh'}));return;}snapshot=applyDelta(snapshot,m);mutations.state(snapshot.revision);status=domain?.dirty?'Unsaved changes':'Saved';schedule();}else if(m.type==='rejected'){mutations.rejected(m.request_id);pending=false;error=m.error.message;}}catch(x){error=String(x);}};socket.onclose=()=>{connection='Disconnected';pending=false;};const observer=new ResizeObserver(()=>requestViewport());observer.observe(viewport);const timer=setInterval(()=>{fps=frames*2;frames=0;},500);return()=>{void listeners.then(xs=>xs.forEach(x=>x()));rgba?.dispose();decoder.dispose();observer.disconnect();clearInterval(timer);socket?.close();};});
</script>

<div class="studio"><header><button class="brand" onclick={()=>showModels=!showModels}>NPR Drawing Studio</button><span>{selectedModel?.label??domain?.scene??'Drawing'}</span><small class:problem={!!error}>{documentStatus}</small><i></i><button disabled={!domain?.can_undo||pending} onclick={()=>dispatch('history',{kind:'undo'})}>Undo</button><button disabled={!domain?.can_redo||pending} onclick={()=>dispatch('history',{kind:'redo'})}>Redo</button><button onclick={reset}>Reset view</button><button class="primary" onclick={()=>dispatch('save',{kind:'save_all'})}>Save</button></header><main>
  <aside class="left"><section><h2>Sources <button onclick={()=>showModels=!showModels}>{showModels?'Hide':'Models'}</button></h2>{#if showModels}<div class="list">{#each visibleModels as model}<button class:active={model.id===settings?.selected} class="model" onclick={()=>selectModel(model)}>{#if model.thumbnail}<img src={model.thumbnail} alt="" />{:else}<b>◇</b>{/if}<span><strong>{model.label}</strong><small>{model.source} · {model.kind}</small></span></button>{/each}</div>{:else}<p>One model per drawing. Switching saves the changed drawing as a Draft.</p>{/if}</section><section><h2>Brushes <small>{brushList.length} presets</small></h2><label>New layer geometry<select bind:value={newSource}>{#each Object.entries(names).filter(([id])=>id!=='paper') as [id,name]}<option value={id}>{name}</option>{/each}</select></label><p>1. Choose geometry. 2. Choose a compatible pinned brush.</p><div class="brush-actions"><button disabled={!chosenBrush||!compatible(chosenBrush,newSource)} onclick={()=>addLayer(chosenBrush)}>Add {names[newSource]} layer</button><button disabled={!chosenBrush||!selectedLayer||!compatible(chosenBrush,selectedLayer.source)} onclick={()=>useBrush(chosenBrush)}>Apply to selected</button></div><div class="list">{#each brushList as brush}<button class:active={chosenBrush?.id===brush.id&&chosenBrush?.version===brush.version} class="brush" disabled={!compatible(brush,newSource)||pending} onclick={()=>chosenBrush=brush}><span class:surface={brush.applications?.includes('surface')} class="swatch"></span><span><strong>{brush.name}</strong><small>{brush.medium} · v{brush.version}</small><small>{brush.applications?.join(', ')}</small></span></button>{/each}</div></section></aside>
  <section class="drawing"><nav><span>Paper viewport · orbit, pan and zoom</span><i></i><button class:active={cameraMode==='select'} onclick={()=>cameraMode='select'}>Select</button><button class:active={cameraMode==='orbit'} onclick={()=>cameraMode='orbit'}>Orbit</button><button class:active={settings?.debug==='FeatureClasses'} onclick={coverage}>Coverage</button></nav><!-- svelte-ignore a11y_no_noninteractive_tabindex, a11y_no_noninteractive_element_interactions --><div class="viewport" bind:this={viewport} tabindex="0" role="application" aria-label="NPR drawing viewport" oncontextmenu={e=>e.preventDefault()} onpointerdown={down} onpointermove={pointerMove} onpointerup={up} onpointercancel={cancel} onwheel={e=>{e.preventDefault();viewport.focus();begin();navigate('zoom',0,0,-wheelPixels(e.deltaY,e.deltaMode,viewport.clientHeight));}}><canvas bind:this={canvas} class:hidden={activeMode==='local_rgba'}></canvas><canvas bind:this={rgbaCanvas} class:hidden={activeMode!=='local_rgba'}></canvas>{#if !settings}<div class="empty">Preparing paper and model…</div>{/if}{#if presentationError}<div class="message">{presentationError}</div>{/if}<small class="hud">{activeMode?'Drawing ready':'Preparing render'} · {fps} FPS · {renderSize[0]}×{renderSize[1]}</small></div><footer><details><summary>Drafts ({Object.keys(drafts).length})</summary>{#each Object.keys(drafts) as id}<button onclick={()=>dispatch('draft.open',{kind:'open_draft',model:id})}>{title(id)}</button>{/each}</details><details><summary>Variants ({Object.keys(variants).length})</summary>{#each Object.keys(variants) as id}<button onclick={()=>dispatch('variant.apply',{kind:'apply_variant',id})}>{title(id)}</button>{/each}</details><label>Build-up <input type="range" min="0" max="1" step=".1" value={buildUp} onchange={e=>setBuildUp(Number(e.currentTarget.value))} /></label></footer></section>
  <aside class="right"><section><h2>Layers <span><button disabled={!selectedLayer||selectedLayer.source==='paper'} onclick={duplicate}>Duplicate</button><button disabled={!selectedLayer||selectedLayer.source==='paper'} onclick={remove}>Delete</button></span></h2><div class="list">{#each layers as layer}<button class:active={layer.id===selectedLayerId} class="layer" onclick={()=>selectedLayerId=layer.id}><span class:paper={layer.source==='paper'} class:paint={surface(layer.source)} class="thumb"></span><span><strong>{layer.label}</strong><small>{names[layer.source]??layer.source} · {Math.round(layer.opacity*100)}%</small></span><em onclick={e=>{e.stopPropagation();update(layer.id,{enabled:!layer.enabled});}}>{layer.enabled?'●':'○'}</em><em onclick={e=>{e.stopPropagation();lock(layer);}}>{(domain?.locked_layers??[]).includes(layer.id)?'🔒':'□'}</em></button>{/each}</div><div class="actions"><button onclick={()=>move(-1)}>Move up</button><button onclick={()=>move(1)}>Move down</button><button class:active={soloLayer===selectedLayerId} onclick={toggleSolo}>Solo</button></div></section>{#if selectedLayer}<section><h2>Layer Inspector <small>{selectedLayer.id}</small></h2><label>Name<input value={selectedLayer.label} onchange={e=>update(selectedLayer.id,{label:e.currentTarget.value})} /></label><label>Opacity <output>{Math.round(selectedLayer.opacity*100)}%</output><input type="range" min="0" max="1" step=".05" value={selectedLayer.opacity} onchange={e=>update(selectedLayer.id,{opacity:Number(e.currentTarget.value)})} /></label><label>Blend<select value={selectedLayer.blend} onchange={e=>update(selectedLayer.id,{blend:e.currentTarget.value})}><option>normal</option><option>multiply</option><option>screen</option></select></label>{#if selectedLayer.hatch}<label>Hatch density<input type="range" min="0" max="1" step=".05" value={selectedLayer.hatch.density} onchange={e=>update(selectedLayer.id,{hatch:{...selectedLayer.hatch,density:Number(e.currentTarget.value)}})} /></label><label>Hatch spacing<input type="range" min=".25" max="4" step=".25" value={selectedLayer.hatch.spacing} onchange={e=>update(selectedLayer.id,{hatch:{...selectedLayer.hatch,spacing:Number(e.currentTarget.value)}})} /></label>{/if}{#if selectedLayer.paint}<label>Wash<input type="range" min="0" max="2" step=".1" value={selectedLayer.paint.wash} onchange={e=>update(selectedLayer.id,{paint:{...selectedLayer.paint,wash:Number(e.currentTarget.value)}})} /></label><label>Granulation<input type="range" min="0" max="1" step=".05" value={selectedLayer.paint.granulation} onchange={e=>update(selectedLayer.id,{paint:{...selectedLayer.paint,granulation:Number(e.currentTarget.value)}})} /></label>{/if}<p class="diag">{#if diagnostics[selectedLayer.id]?.no_effect_reason}No effect: {diagnostics[selectedLayer.id].no_effect_reason}{:else}Source {diagnostics[selectedLayer.id]?.source_geometry??0} · marks {diagnostics[selectedLayer.id]?.generated_marks??0} · mask {Math.round((diagnostics[selectedLayer.id]?.mask_coverage??0)*100)}%{/if}</p></section>{/if}<section><h2>Paper & Palette</h2><p>Paper, palette and saved compositions are presets. Marks belong to individual layers.</p>{#each looks as id}<button class="preset" onclick={()=>dispatch('preset.apply',{kind:'use_look',id})}>{title(id)}</button>{/each}</section></aside>
</main></div>

<style>
:global(*){box-sizing:border-box}:global(body){margin:0;background:#111315;color:#e8e5df;font:13px/1.4 Inter,"Segoe UI",sans-serif}:global(button),:global(input),:global(select){font:inherit}:global(button){border:1px solid #41413e;border-radius:6px;background:#272826;color:inherit;padding:6px 8px;cursor:pointer}:global(button:hover:not(:disabled)){background:#393a36}:global(button:disabled){opacity:.45;cursor:default}:global(button:focus-visible),:global(input:focus-visible),:global(select:focus-visible){outline:2px solid #d3aa65;outline-offset:2px}.studio{height:100dvh;display:grid;grid-template-rows:52px minmax(0,1fr);overflow:hidden}.studio>header{display:flex;align-items:center;gap:10px;padding:0 14px;border-bottom:1px solid #363632;background:#20211e}.brand{border:0;background:transparent;padding-left:0;color:#fbf6eb;font-weight:700}.studio header small{color:#9ebea2}.problem{color:#ee9a87!important}.studio header i,nav i{flex:1}main{display:grid;grid-template-columns:260px minmax(360px,1fr) 300px;min-height:0}aside{min-height:0;overflow:auto;background:#20211e}.left{border-right:1px solid #363632}.right{border-left:1px solid #363632}aside section{padding:13px;border-bottom:1px solid #363632}h2{display:flex;align-items:center;justify-content:space-between;gap:6px;margin:0 0 10px;color:#f7f1e4;font-size:13px}small,p{color:#a8a79f;font-size:11px}p{margin:0 0 10px}.list{display:grid;gap:6px}.model,.brush,.layer{display:flex;align-items:center;gap:8px;width:100%;text-align:left}.model.active,.layer.active,.brush.active{border-color:#c49a54;background:#38342a;box-shadow:inset 3px 0 #d3aa65}.model img,.model b{display:grid;width:34px;height:34px;place-items:center;object-fit:contain;background:#171816;color:#c5b188}.model strong,.brush strong,.layer strong{display:block;font-weight:600}.brush .swatch,.thumb{width:30px;height:30px;flex:0 0 auto;border-radius:4px;background:repeating-linear-gradient(-25deg,#e4dbc7 0 3px,#4c483e 3px 5px)}.brush .surface,.thumb.paint{background:linear-gradient(135deg,#ceb78a,#745f48)}.thumb.paper{background:#ede6d6}.layer>span:nth-child(2){flex:1}.layer em{font-style:normal;color:#cdb378}.actions,.brush-actions{display:flex;gap:5px;margin:8px 0}.actions button,.brush-actions button{padding:4px 6px;font-size:11px}.actions .active,nav .active{border-color:#b58d4c;background:#51432a;color:#fff8e9}label{display:grid;gap:4px;margin:9px 0;color:#c8c6be;font-size:11px}input,select{width:100%;accent-color:#c69b55}input:not([type=range]),select{border:1px solid #484942;border-radius:4px;background:#151613;color:#e8e5df;padding:5px}output{float:right;color:#d3aa65}.diag{margin:11px 0 0;padding:7px;border-radius:4px;background:#171816}.preset{width:100%;margin-top:5px;text-align:left}.drawing{display:grid;grid-template-rows:42px minmax(0,1fr) 38px;min-width:0;min-height:0;background:#141512}.drawing nav,.drawing footer{display:flex;align-items:center;gap:7px;padding:6px 10px;border-bottom:1px solid #30312d;color:#989a90;font-size:11px}.drawing nav button,.drawing footer button{padding:4px 7px;font-size:11px}.viewport{position:relative;min-height:0;overflow:hidden;outline:none}canvas{display:block;width:100%;height:100%;object-fit:contain;touch-action:none}.hidden{visibility:hidden}.empty{position:absolute;inset:0;display:grid;place-items:center;color:#a6a89b}.message{position:absolute;top:12px;right:12px;padding:8px;background:#321f1d;color:#efad9f}.hud{position:absolute;bottom:12px;left:12px;padding:5px 8px;border-radius:4px;background:#12130fcc;color:#bbb9ad;pointer-events:none}.drawing footer{border-top:1px solid #30312d;border-bottom:0}.drawing footer label{display:block;margin:0 0 0 auto}.drawing footer input{width:100px;vertical-align:middle}@media(max-width:900px){main{grid-template-columns:220px minmax(0,1fr) 250px}}@media(max-width:680px){.studio{height:auto;min-height:100dvh}.studio>header{position:sticky;top:0;z-index:2}.studio header>span,.studio header small{display:none}main{grid-template-columns:1fr;grid-template-rows:auto 60dvh auto}.left,.right{border:0}.left{max-height:260px}.right{max-height:520px}}
</style>
